from engine import span
def build(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    P = []
    P.append(dict(role='purpose', text='La información del ADN se convierte en proteínas con la ayuda del ARN. Este capítulo explica la transcripción y la traducción, qué es el código genético y por qué tiene 64 codones, cómo se descifró y qué significa que sea redundante pero no ambiguo, y termina con un cálculo de cuántos codones corresponden, de media, a cada aminoácido.',
        quotes=[Q('nhgri_code','Genetic code refers to the instructions contained in a gene that tell a cell how to make a specific protein.'), Q('es_codigo','El código genético es el conjunto de reglas que define cómo se traduce una secuencia de nucleótidos en el ARN a una secuencia de aminoácidos en una proteína.')]))
    P.append(dict(text='La transcripción es el proceso de hacer una copia de ARN de la secuencia de ADN de un gen. Esa copia, llamada ARN mensajero (ARNm), lleva la información proteica codificada en el ADN. En los humanos y otros organismos complejos, el ARNm pasa del núcleo al citoplasma, donde se usa para sintetizar la proteína codificada. La traducción es el proceso por el que la información del ARNm dirige la adición de aminoácidos durante la síntesis de proteínas, y tiene lugar en los ribosomas del citoplasma.',
        quotes=[Q('nhgri_transcription','Transcription, as related to genomics, is the process of making an RNA copy of a gene’s DNA sequence.'), Q('nhgri_transcription','In humans and other complex organisms, mRNA moves from the cell nucleus to the cell cytoplasm'), Q('nhgri_translation','Translation takes place on ribosomes in the cell cytoplasm, where mRNA is read and translated into the string of amino acid chains that make up the synthesized protein.')]))
    P.append(dict(text='La traducción la realiza el ribosoma, que une los aminoácidos en el orden que especifica el ARN mensajero, usando moléculas de ARN de transferencia (ARNt) que transportan los aminoácidos y leen el ARNm de tres en tres nucleótidos. El código genético es muy similar en todos los organismos y puede expresarse en una tabla sencilla de 64 entradas. Es común a todos los seres vivos y todos los virus, aunque hay pequeñas variaciones, lo que indica un origen único y que es universal, al menos en el contexto de nuestro planeta.',
        quotes=[Q('en_code','Translation is accomplished by the ribosome, which links proteinogenic amino acids in an order specified by messenger RNA (mRNA), using transfer RNA (tRNA) molecules to carry amino acids and to read the mRNA three nucleotides at a time.'), Q('en_code','can be expressed in a simple table with 64 entries'), Q('es_codigo','Este código es común en todos los seres vivos y todos los virus (aunque hay pequeñas variaciones)')]))
    P.append(dict(text='La razón del número 64 es combinatoria. El material genético se compone de cuatro bases, que se representan con las letras A, T, G y C en el ADN y A, U, G y C en el ARN. Un codón es una secuencia de tres nucleótidos, así que el número de codones posibles es 4 × 4 × 4 = 64. De ellos, 61 codifican aminoácidos, entre ellos el codón de inicio AUG, y los tres restantes, UAA, UAG y UGA, son sitios de parada. El glosario del instituto de genómica lo confirma: hay 64 codones diferentes, 61 que especifican aminoácidos y 3 señales de parada.',
        quotes=[Q('es_codigo','el número de codones posibles es 64','los tres restantes son sitios de parada (UAA, llamado ocre; UAG, llamado ámbar; UGA, llamado ópalo)'), Q('nhgri_codon','There are 64 different codons: 61 specify amino acids and 3 are used as stop signals.'), Q('en_code','Protein-coding frames are defined by a start codon, usually the first AUG codon in the RNA, (ATG in DNA) sequence.')]))
    P.append(dict(text='¿Por qué tripletes y no pares? Con cuatro bases, dos nucleótidos darían solo 4 × 4 = 16 combinaciones, menos que los veinte aminoácidos que hay que codificar. Hacen falta al menos tres. Esa inferencia aritmética es la que anticipó George Gamow, que fue el primero en dar un esquema viable de síntesis de proteínas a partir del ADN, postulando que grupos de tres bases debían codificar cada aminoácido. La primera demostración experimental de que los codones constan de tres nucleótidos la proporcionó el experimento de Crick, Brenner y colaboradores.',
        quotes=[Q('en_code','Soviet-American physicist George Gamow was the first to give a workable scheme for protein synthesis from DNA.'), Q('es_codigo','La primera demostración de que los codones constan de tres nucleótidos la proporcionó el experimento de Crick, Brenner y colaboradores.'), Q('en_code','the club could have only 20 permanent members to represent each of the 20 amino acids')]))
    P.append(dict(text='El código se descifró experimentalmente en los años sesenta. En 1961, Marshall Nirenberg y Heinrich Matthaei revelaron la primera correspondencia entre un codón y un aminoácido. Con un sistema sin células tradujeron una secuencia de ARN de poliuracilo, UUUU..., y vieron que el polipéptido sintetizado solo contenía fenilalanina, con lo que dedujeron que el codón UUU especifica fenilalanina. Antes, en 1955, Severo Ochoa y Marianne Grunberg-Manago habían aislado la enzima polinucleótido fosforilasa, capaz de sintetizar ARNm sin molde.',
        quotes=[Q('en_code','Marshall Nirenberg and J. Heinrich Matthaei were the first to reveal the nature of a codon in 1961.'), Q('en_code','discovered that the polypeptide that they had synthesized consisted of only the amino acid phenylalanine'), Q('es_codigo','En 1955, Severo Ochoa y Marianne Grunberg-Manago aislaron la enzima polinucleótido fosforilasa')]))
    P.append(dict(text='El código tiene redundancia, pero no ambigüedad. Por ejemplo, los codones GAA y GAG especifican ambos el ácido glutámico, pero ningún codón especifica dos aminoácidos distintos. Las diferencias entre los codones que codifican un mismo aminoácido suelen estar en la tercera posición, y por eso la tolerancia al cambio es mayor en esa posición que en la primera y la segunda. A esta redundancia se le llama degeneración. Es una propiedad que se puede cuantificar: con 61 codones con sentido para 20 aminoácidos, el promedio es de 3,05 codones por aminoácido, aunque no todos los aminoácidos tienen el mismo número.',
        quotes=[Q('es_codigo','El código genético tiene redundancia, pero no ambigüedad.'), Q('en_code','Degeneracy is the redundancy of the genetic code.'), Q('es_codigo','Las diferencias entre los codones que codifican un mismo aminoácido presentan diferencias en la tercera posición.')]))
    P.append(dict(text='El ADN y el ARN usan bases distintas: en el ARN el uracilo sustituye a la timina. La secuencia del ADN que se transcribe a ARN tiene por tanto una T allí donde el ARNm tiene una U, y por eso el codón de inicio se escribe AUG en el ARN y ATG en el ADN. El código estándar es el que usa la gran mayoría de los genes, pero existen códigos variantes, como el de las mitocondrias, de modo que el mismo codón puede significar otra cosa en ellas.',
        quotes=[Q('es_codigo','adenina (A), timina (T), guanina (G) y citosina (C) en el ADN y adenina (A), uracilo (U), guanina (G) y citosina (C) en el ARN'), Q('en_code','though variant codes (such as in mitochondria) exist')]))
    P.append(dict(role='definition', text='Codón: secuencia de tres nucleótidos de ADN o de ARN que forma una unidad de información genómica y codifica un aminoácido concreto o una señal de parada de la síntesis de proteínas.',
        quotes=[Q('nhgri_codon','A codon is a DNA or RNA sequence of three nucleotides (a trinucleotide) that forms a unit of genomic information encoding a particular amino acid or signaling the termination of protein synthesis (stop signals).'), Q('es_codigo','El código define la relación entre cada secuencia de tres nucleótidos, llamada codón, y cada aminoácido.')]))
    P.append(dict(role='consejo', text='Para leer una secuencia de ARNm, localice primero el codón de inicio AUG y divida a partir de ahí en grupos de tres letras hasta un codón de parada. Si empieza en una posición distinta, cambia todo el marco de lectura.',
        quotes=[Q('en_code','Protein-coding frames are defined by a start codon, usually the first AUG codon in the RNA, (ATG in DNA) sequence.'), Q('nhgri_codon','A codon is a DNA or RNA sequence of three nucleotides (a trinucleotide)')]))
    P.append(dict(role='self_check', text='¿Por qué el código usa tripletes y no pares de bases? ¿Cuántos codones especifican aminoácidos y cuántos son señales de parada? ¿Qué quiere decir que el código sea redundante pero no ambiguo?',
        quotes=[Q('nhgri_codon','61 specify amino acids and 3 are used as stop signals'), Q('es_codigo','ningún codón especifica dos aminoácidos distintos')]))
    return P

def problems(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    return [dict(role='worked', problem_type='NUMERICAL',
        prompt='El código genético tiene cuatro bases y codones de tres nucleótidos; las fuentes dicen que 61 codones especifican aminoácidos y que hay 20 aminoácidos. Calcule cuántos codones hay en total, cuántos habría con codones de dos nucleótidos y cuántos codones con sentido corresponden, de media, a cada aminoácido.',
        expected='3.05', quotes=[Q('nhgri_codon','There are 64 different codons: 61 specify amino acids and 3 are used as stop signals.'), Q('en_code','the club could have only 20 permanent members to represent each of the 20 amino acids')],
        method='Combinatoria de secuencias y reparto promedio',
        solution=dict(given=[dict(symbol='b',value=4,unit='dimensionless',meaning='bases distintas'),dict(symbol='n_s',value=61,unit='dimensionless',meaning='codones con sentido'),dict(symbol='a',value=20,unit='dimensionless',meaning='aminoácidos')],
          unknown='Los codones de tres nucleótidos, los de dos y los codones por aminoácido.',
          model=[dict(name='Codones de longitud k',latex='N_k = b^{k}',symbolic='b**k'),dict(name='Codones por aminoácido',latex='\\bar{c} = n_s / a',symbolic='n_s/a')],
          assumptions=['Se cuentan los 20 aminoácidos canónicos.','Cada posición del codón puede ser cualquiera de las cuatro bases.'],
          development=['Un código de longitud 2 daría 16 palabras, que no bastan para 20 aminoácidos, así que hace falta como mínimo la longitud 3.'],
          steps=[dict(text='Codones de tres nucleótidos',equation='N_3 = 4^3',expression='4**3',expected=64,unit='dimensionless'),
                 dict(text='Codones de dos nucleótidos',equation='N_2 = 4^2',expression='4**2',expected=16,unit='dimensionless'),
                 dict(text='Codones con sentido por aminoácido',equation='\\bar{c} = 61/20',expression='61/20',expected=3.05,unit='dimensionless')],
          result='Hay 64 codones de tres nucleótidos, frente a solo 16 de dos; y a cada aminoácido le corresponden, de media, 3,05 codones con sentido.',
          interpretation='16 < 20 explica por qué hacen falta tripletes, y 64 > 20 explica la redundancia del código.',
          limitations=['El promedio oculta la distribución: algunos aminoácidos tienen un solo codón y otros seis.'],
          mistakes=['Dividir 64 entre 20 y contar los tres codones de parada como si codificaran aminoácidos.']))]
